import pandas as pd
import numpy as np
import json
import sys

def to_float(x, nd=2):
    return round(float(x), nd)

def main():
    df = pd.read_csv(sys.argv[1])
    facts = []

    # --- TOTALS ---
    total_rev_tw = df['Revenue_TW'].sum(skipna=True)
    total_rev_lw = df['Revenue_LW'].sum(skipna=True)
    total_rev_ly = df['Revenue_LY'].sum(skipna=True)
    total_units_tw = df['Units_TW'].sum(skipna=True)
    total_units_lw = df['Units_LW'].sum(skipna=True)
    total_orders_tw = df['Orders_TW'].sum(skipna=True)
    total_orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": to_float(total_rev_tw),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": to_float(total_rev_lw),
        "formula": "sum(Revenue_LW)"
    })
    if df['Revenue_LY'].notna().any():
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": to_float(total_rev_ly),
            "formula": "sum(Revenue_LY)"
        })

    if total_rev_lw != 0 and not np.isnan(total_rev_lw):
        wow_total = (total_rev_tw - total_rev_lw) / total_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": to_float(wow_total, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if total_rev_ly != 0 and not np.isnan(total_rev_ly):
        yoy_total = (total_rev_tw - total_rev_ly) / total_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": to_float(yoy_total, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(total_units_tw),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": to_float(total_units_lw),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": to_float(total_orders_tw),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": to_float(total_orders_lw),
        "formula": "sum(Orders_LW)"
    })

    # --- TOP ENTITIES BY RANK ---
    top_n = df.dropna(subset=['Rank']).sort_values('Rank').head(3)
    for _, row in top_n.iterrows():
        ent = row['Entity']
        if pd.notna(row['Revenue_TW']):
            facts.append({
                "entity": ent, "metric": "revenue", "period": "TW",
                "value": to_float(row['Revenue_TW']),
                "formula": "Revenue_TW"
            })
        if pd.notna(row['Share_Pct']):
            facts.append({
                "entity": ent, "metric": "share", "period": "TW",
                "value": to_float(row['Share_Pct'], 1),
                "formula": "Share_Pct"
            })
        if pd.notna(row['Rank']):
            facts.append({
                "entity": ent, "metric": "rank", "period": "TW",
                "value": to_float(row['Rank'], 0),
                "formula": "Rank"
            })

    # --- BIGGEST WoW MOVERS ---
    wow_valid = df.dropna(subset=['WoW_Pct'])
    if not wow_valid.empty:
        max_row = wow_valid.loc[wow_valid['WoW_Pct'].idxmax()]
        min_row = wow_valid.loc[wow_valid['WoW_Pct'].idxmin()]
        facts.append({
            "entity": max_row['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(max_row['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100 (max)"
        })
        if min_row['Entity'] != max_row['Entity']:
            facts.append({
                "entity": min_row['Entity'], "metric": "revenue", "period": "WoW",
                "value": to_float(min_row['WoW_Pct'], 1),
                "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100 (min)"
            })

    # --- BIGGEST YoY MOVERS ---
    yoy_valid = df.dropna(subset=['YoY_Pct'])
    if not yoy_valid.empty:
        max_row = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmax()]
        min_row = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmin()]
        facts.append({
            "entity": max_row['Entity'], "metric": "revenue", "period": "YoY",
            "value": to_float(max_row['YoY_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100 (max)"
        })
        if min_row['Entity'] != max_row['Entity']:
            facts.append({
                "entity": min_row['Entity'], "metric": "revenue", "period": "YoY",
                "value": to_float(min_row['YoY_Pct'], 1),
                "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100 (min)"
            })

    # --- TOP ENTITY BY UNITS / ORDERS ---
    if df['Units_TW'].notna().any():
        top_units = df.loc[df['Units_TW'].idxmax()]
        facts.append({
            "entity": top_units['Entity'], "metric": "units", "period": "TW",
            "value": to_float(top_units['Units_TW'], 0),
            "formula": "max(Units_TW)"
        })

    if df['Orders_TW'].notna().any():
        top_orders = df.loc[df['Orders_TW'].idxmax()]
        facts.append({
            "entity": top_orders['Entity'], "metric": "orders", "period": "TW",
            "value": to_float(top_orders['Orders_TW'], 0),
            "formula": "max(Orders_TW)"
        })

    # Cap at 25 facts
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
